/** Every taught word of the line becomes a vocabulary row, in the teaching order of TARGETS. A line
 * like «Да, мо́локо го́рячее.» teaches three of them, and the word lab needs all three: a row is what
 * gives a word its Persian gloss, and the first row is only the word the studio drills aloud. */
function targets(line: StarterLine): Array<{ word: string; meaning: string }> {
  const tokens = line.text.toLowerCase().match(/[а-яё\u0301]+/gu) ?? [];
  const flat = tokens.map(t => t.replace(/\u0301/g, ''));
  const rows: Array<{ word: string; meaning: string }> = [];
  for (const [key, meaning] of Object.entries(TARGETS)) {
    const at = flat.indexOf(key);
    if (at < 0 || rows.some(row => row.word === tokens[at])) continue;
    rows.push({ word: tokens[at], meaning });
  }
  return rows.length ? rows : [{ word: line.text.replace(/[.,?!]+$/, ''), meaning: line.fa }];
}
export const RUSSIAN_PRE_A1_LESSONS: readonly LearningLesson[] = RUSSIAN_STARTER_STEPS.map((s, index) => {
  const id = `ru-pre-${s.id}`;
  const lines = [...s.oral, ...s.read];
  const sentences = lines.map((line, i) => ({ ...line, id: `${id}-${String(i + 1).padStart(2, '0')}`,
    vocabulary: targets(line),
    ...(i === 0 ? { pattern: s.goal } : {}) }));
  const dialogue = [s.oral[0], s.oral[1], s.oral[2], s.oral[5], s.ending].map((line, i) => ({ ...line, speaker: i % 2 === 0 ? 'هم‌صحبت' : 'زبان‌آموز' }));
  return { id, title: s.title, situation: s.goal, durationMinutes: 6, teachingFa: s.note, sentences, dialogue,
    checks: orderChecks([
      { promptFa: 'عبارت را گوش کن. گوینده چه می‌گوید؟', choices: [s.oral[2].fa, s.oral[0].fa, s.oral[4].fa, s.oral[3].fa], correctIndex: 0, explanationFa: `${s.oral[2].text} یعنی «${s.oral[2].fa}»` },
      { promptFa: s.situationCheck, choices: [1, 3, 0, 5].map(i => s.oral[i].text), correctIndex: 0, explanationFa: `${s.oral[1].text} — ${s.oral[1].fa}` },
      { promptFa: `این نوشته را خودت بخوان: «${s.read[1].text}». چه معنی دارد؟`, choices: [s.read[1].fa, s.read[0].fa, s.oral[0].fa, s.oral[4].fa], correctIndex: 0, explanationFa: `${s.read[1].pronunciation} — ${s.read[1].fa}` },
    ], index) };
});
